static double median(int[] a, int[] b) {
    if (a.length > b.length) return median(b, a);
    int n = a.length;
    int m = b.length;
    long total = (long) n + m;
    if (total == 0) throw new IllegalArgumentException("No values");
    int leftSize = (int) ((total + 1) / 2);
    int low = 0;
    int high = n;
    while (low <= high) {
        int cutA = low + (high - low) / 2;
        int cutB = leftSize - cutA;
        long leftA = cutA == 0 ? Long.MIN_VALUE : a[cutA - 1];
        long rightA = cutA == n ? Long.MAX_VALUE : a[cutA];
        long leftB = cutB == 0 ? Long.MIN_VALUE : b[cutB - 1];
        long rightB = cutB == m ? Long.MAX_VALUE : b[cutB];
        if (leftA <= rightB && leftB <= rightA) {
            long middleLeft = Math.max(leftA, leftB);
            if (total % 2 == 1) return middleLeft;
            long middleRight = Math.min(rightA, rightB);
            return (middleLeft + middleRight) / 2.0;
        }
        if (leftA > rightB) {
            high = cutA - 1;
        } else {
            low = cutA + 1;
        }
    }
    throw new IllegalArgumentException("Inputs must be sorted");
}

