static Node reverseKGroup(Node head, int k) {
    if (k < 1) throw new IllegalArgumentException("k must be positive");
    if (head == null || k == 1) return head;
    Node current = head;
    Node previousTail = null;
    while (current != null) {
        Node kth = kthNode(current, k);
        if (kth == null) {
            if (previousTail != null) previousTail.next = current;
            break;
        }
        Node nextGroup = kth.next;
        kth.next = null;
        Node groupHead = reverse(current);
        if (previousTail == null) head = groupHead;
        else previousTail.next = groupHead;
        previousTail = current;
        current = nextGroup;
    }
    return head;
}

