static Node rotateRight(Node head, int k) {
    if (k < 0) throw new IllegalArgumentException("k must be nonnegative");
    if (head == null || head.next == null || k == 0) return head;
    int length = 1;
    Node tail = head;
    while (tail.next != null) {
        tail = tail.next;
        length++;
    }
