static int myAtoi(String s) {
    int index = 0;
    while (index < s.length() && s.charAt(index) == ' ') index++;
    int sign = 1;
    if (index < s.length() && (s.charAt(index) == '+' || s.charAt(index) == '-')) {
        if (s.charAt(index) == '-') sign = -1;
        index++;
    }
    long limit = sign == 1 ? Integer.MAX_VALUE : 2147483648L;
    long magnitude = readDigits(s, index, 0, limit);
    return (int) (sign * magnitude);
}

static long readDigits(String s, int index, long value, long limit) {
    if (index == s.length()) return value;
    char ch = s.charAt(index);
    if (ch < '0' || ch > '9') return value;
    int digit = ch - '0';
    if (value > (limit - digit) / 10) return limit;
    return readDigits(s, index + 1, value * 10 + digit, limit);
}

