static boolean findWord(char[][] board, String word, int row, int col, int index) {
    if (row < 0 || row >= board.length || col < 0 || col >= board[0].length
            || board[row][col] != word.charAt(index)) return false;
    if (index == word.length() - 1) return true;
    char saved = board[row][col];
    board[row][col] = '#';
    boolean found = findWord(board, word, row + 1, col, index + 1)
        || findWord(board, word, row - 1, col, index + 1)
        || findWord(board, word, row, col + 1, index + 1)
        || findWord(board, word, row, col - 1, index + 1);
    board[row][col] = saved;
    return found;
}

