static void placeQueens(int col, char[][] board, boolean[] rows,
                        boolean[] rising, boolean[] falling,
                        List<List<String>> answer) {
    int n = board.length;
    if (col == n) {
        List<String> snapshot = new ArrayList<>();
        for (char[] row : board) snapshot.add(new String(row));
        answer.add(snapshot);
        return;
    }
    for (int row = 0; row < n; row++) {
        int a = row + col;
        int b = n - 1 + col - row;
        if (rows[row] || rising[a] || falling[b]) continue;
        rows[row] = rising[a] = falling[b] = true;
        board[row][col] = 'Q';
        placeQueens(col + 1, board, rows, rising, falling, answer);
        board[row][col] = '.';
        rows[row] = rising[a] = falling[b] = false;
    }
}

