static void walkMaze(int[][] maze, int row, int col, StringBuilder path,
                     List<String> answer) {
    int n = maze.length;
    if (row == n - 1 && col == n - 1) {
        answer.add(path.toString());
        return;
    }
    maze[row][col] = 0;
    int[] dr = {1, 0, 0, -1};
    int[] dc = {0, -1, 1, 0};
    String moves = "DLRU";
    for (int i = 0; i < 4; i++) {
        int nr = row + dr[i], nc = col + dc[i];
        if (nr < 0 || nr >= n || nc < 0 || nc >= n || maze[nr][nc] == 0) continue;
        path.append(moves.charAt(i));
        walkMaze(maze, nr, nc, path, answer);
        path.deleteCharAt(path.length() - 1);
    }
    maze[row][col] = 1;
}

