static boolean graphColoring(int n, int[][] edges, int m) {
    boolean[][] adjacent = new boolean[n][n];
    for (int[] edge : edges) {
        if (edge[0] == edge[1]) return false;
        adjacent[edge[0]][edge[1]] = true;
        adjacent[edge[1]][edge[0]] = true;
    }
    return colourVertex(0, adjacent, new int[n], m);
}

static boolean colourVertex(int vertex, boolean[][] adjacent, int[] colours, int m) {
    if (vertex == colours.length) return true;
    for (int colour = 1; colour <= m; colour++) {
        boolean safe = true;
        for (int neighbour = 0; neighbour < colours.length; neighbour++) {
            if (adjacent[vertex][neighbour] && colours[neighbour] == colour) {
                safe = false;
                break;
            }
        }
        if (!safe) continue;
        colours[vertex] = colour;
        if (colourVertex(vertex + 1, adjacent, colours, m)) return true;
        colours[vertex] = 0;
    }
    return false;
}

