static void solveSudoku(char[][] board) {
    if (!fillSudoku(board)) throw new IllegalArgumentException("No solution");
}

static boolean fillSudoku(char[][] board) {
    for (int row = 0; row < 9; row++) {
        for (int col = 0; col < 9; col++) {
            if (board[row][col] != '.') continue;
            for (char digit = '1'; digit <= '9'; digit++) {
                if (!safeDigit(board, row, col, digit)) continue;
                board[row][col] = digit;
                if (fillSudoku(board)) return true;
                board[row][col] = '.';
            }
            return false;
        }
    }
    return true;
}

static boolean safeDigit(char[][] board, int row, int col, char digit) {
    for (int i = 0; i < 9; i++) {
        if (board[row][i] == digit || board[i][col] == digit) return false;
        int boxRow = 3 * (row / 3) + i / 3;
        int boxCol = 3 * (col / 3) + i % 3;
        if (board[boxRow][boxCol] == digit) return false;
    }
    return true;
}

