static void expressions(String num, int start, long target, long total, long last,
                         StringBuilder current, List<String> answer) {
    if (start == num.length()) {
        if (total == target) answer.add(current.toString());
        return;
    }
    long value = 0;
    int savedLength = current.length();
    for (int end = start; end < num.length(); end++) {
        if (end > start && num.charAt(start) == '0') break;
        value = value * 10 + num.charAt(end) - '0';
        if (start == 0) {
            current.append(num, start, end + 1);
            expressions(num, end + 1, target, value, value, current, answer);
            current.setLength(savedLength);
            continue;
        }
        current.append('+').append(num, start, end + 1);
        expressions(num, end + 1, target, total + value, value, current, answer);
        current.setLength(savedLength);
        current.append('-').append(num, start, end + 1);
        expressions(num, end + 1, target, total - value, -value, current, answer);
        current.setLength(savedLength);
        current.append('*').append(num, start, end + 1);
        expressions(num, end + 1, target, total - last + last * value,
                    last * value, current, answer);
        current.setLength(savedLength);
    }
}

