static List<List<Integer>> factorWithSieve(int[] queries) {
    int maximum = 1;
    for (int value : queries) maximum = Math.max(maximum, value);
    int[] smallest = new int[maximum + 1];
    for (int value = 2; value <= maximum; value++) smallest[value] = value;
    for (int prime = 2; prime <= maximum / prime; prime++) {
        if (smallest[prime] != prime) continue;
        for (int multiple = prime * prime; multiple <= maximum; multiple += prime) {
            if (smallest[multiple] == multiple) smallest[multiple] = prime;
        }
    }
    List<List<Integer>> answer = new ArrayList<>();
    for (int original : queries) {
        List<Integer> factors = new ArrayList<>();
        int value = original;
        while (value > 1) {
            int prime = smallest[value];
            factors.add(prime);
            value /= prime;
        }
        answer.add(factors);
    }
    return answer;
}

