static class MinStack {
    private final Deque<Long> stack = new ArrayDeque<>();
    private long minimum;

    void push(int value) {
        long x = value;
        if (stack.isEmpty()) {
            stack.push(x);
            minimum = x;
        } else if (x < minimum) {
            stack.push(2L * x - minimum);
            minimum = x;
        } else {
            stack.push(x);
        }
    }
    void pop() {
        long stored = stack.pop();
        if (stored < minimum) minimum = 2L * minimum - stored;
    }
    int top() {
        long stored = stack.element();
        return (int) (stored < minimum ? minimum : stored);
    }
    int getMin() {
        if (stack.isEmpty()) throw new NoSuchElementException("Stack empty");
        return (int) minimum;
    }
}

