static class LFUCache {
    private static class Entry {
        int value, frequency = 1;
        Entry(int value) { this.value = value; }
    }
    private final int capacity;
    private int minFrequency = 0;
    private final Map<Integer, Entry> entries = new HashMap<>();
    private final Map<Integer, LinkedHashSet<Integer>> groups = new HashMap<>();

    LFUCache(int capacity) {
        if (capacity < 0) throw new IllegalArgumentException("Negative capacity");
        this.capacity = capacity;
    }

    public int get(int key) {
        Entry entry = entries.get(key);
        if (entry == null) return -1;
        touch(key, entry);
        return entry.value;
    }

    public void put(int key, int value) {
        Entry entry = entries.get(key);
        if (entry != null) {
            entry.value = value;
            touch(key, entry);
            return;
        }
        if (capacity == 0) return;
        if (entries.size() == capacity) {
            LinkedHashSet<Integer> least = groups.get(minFrequency);
            int victim = least.iterator().next();
            least.remove(victim);
            if (least.isEmpty()) groups.remove(minFrequency);
            entries.remove(victim);
        }
        entries.put(key, new Entry(value));
        groups.computeIfAbsent(1, ignored -> new LinkedHashSet<>()).add(key);
        minFrequency = 1;
    }

    private void touch(int key, Entry entry) {
        int oldFrequency = entry.frequency;
        LinkedHashSet<Integer> oldGroup = groups.get(oldFrequency);
        oldGroup.remove(key);
        if (oldGroup.isEmpty()) {
            groups.remove(oldFrequency);
            if (minFrequency == oldFrequency) minFrequency++;
        }
        entry.frequency++;
        groups.computeIfAbsent(entry.frequency, ignored -> new LinkedHashSet<>()).add(key);
    }
}

