static class BinaryHeap {
    private final List<Integer> values = new ArrayList<>();
    private final boolean minHeap;
    BinaryHeap(boolean minHeap) { this.minHeap = minHeap; }

    private boolean before(int a, int b) { return minHeap ? a < b : a > b; }
    public void initializeHeap() { values.clear(); }
    public int heapSize() { return values.size(); }
    public boolean isEmpty() { return values.isEmpty(); }

    public void insert(int value) {
        values.add(value);
        siftUp(values.size() - 1);
    }

    public void changeKey(int index, int value) {
        if (index < 0 || index >= values.size()) throw new IndexOutOfBoundsException(index);
        values.set(index, value);
        if (index > 0 && before(value, values.get((index - 1) / 2))) siftUp(index);
        else siftDown(index);
    }

    protected int root() {
        if (isEmpty()) throw new NoSuchElementException("Empty heap");
        return values.get(0);
    }

    protected void removeRoot() {
        if (isEmpty()) throw new NoSuchElementException("Empty heap");
        int last = values.remove(values.size() - 1);
        if (!values.isEmpty()) {
            values.set(0, last);
            siftDown(0);
        }
    }

    private void siftUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (!before(values.get(index), values.get(parent))) break;
            Collections.swap(values, index, parent);
            index = parent;
        }
    }

    private void siftDown(int index) {
        while (index < values.size() / 2) {
            int child = 2 * index + 1;
            int right = child + 1;
            if (right < values.size() && before(values.get(right), values.get(child))) child = right;
            if (!before(values.get(child), values.get(index))) break;
            Collections.swap(values, index, child);
            index = child;
        }
    }
}

static class MinHeap extends BinaryHeap {
    MinHeap() { super(true); }
    public int getMin() { return root(); }
    public void extractMin() { removeRoot(); }
}

static class MaxHeap extends BinaryHeap {
    MaxHeap() { super(false); }
    public int getMax() { return root(); }
    public void extractMax() { removeRoot(); }
}

