static boolean isNStraightHand(int[] hand, int groupSize) {
    if (groupSize <= 0 || hand.length % groupSize != 0) return false;
    TreeMap<Integer, Integer> counts = new TreeMap<>();
    for (int value : hand) counts.merge(value, 1, Integer::sum);
    while (!counts.isEmpty()) {
        int start = counts.firstKey();
        for (int offset = 0; offset < groupSize; offset++) {
            long required = (long) start + offset;
            if (required > Integer.MAX_VALUE) return false;
            int value = (int) required;
            Integer count = counts.get(value);
            if (count == null) return false;
            if (count == 1) counts.remove(value);
            else counts.put(value, count - 1);
        }
    }
    return true;
}

