static int[] maximumSumCombinations(int[] first, int[] second, int count) {
    int n = first.length;
    if (second.length != n || count < 0 || count > (long) n * n)
        throw new IllegalArgumentException("Invalid lengths or count");
    if (count == 0) return new int[0];
    int[] a = first.clone(), b = second.clone();
    Arrays.sort(a);
    Arrays.sort(b);
    PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(y[0], x[0]));
    Set<Long> visited = new HashSet<>();
    heap.offer(new int[]{a[n - 1] + b[n - 1], n - 1, n - 1});
    visited.add((long) (n - 1) * n + n - 1);
    int[] result = new int[count];
    for (int p = 0; p < count; p++) {
        int[] cell = heap.poll();
        result[p] = cell[0];
        int i = cell[1], j = cell[2];
        if (i > 0 && visited.add((long) (i - 1) * n + j))
            heap.offer(new int[]{a[i - 1] + b[j], i - 1, j});
        if (j > 0 && visited.add((long) i * n + j - 1))
            heap.offer(new int[]{a[i] + b[j - 1], i, j - 1});
    }
    return result;
}

