static double fractionalKnapsack(int[] values, int[] weights, int capacity) {
    int n = values.length;
    int[][] items = new int[n][2];
    for (int i = 0; i < n; i++) {
        items[i][0] = values[i];
        items[i][1] = weights[i];
    }
    Arrays.sort(items, (a, b) -> Long.compare((long) b[0] * a[1], (long) a[0] * b[1]));
    double total = 0;
    int remaining = capacity;
    for (int[] item : items) {
        if (remaining == 0) break;
        int taken = Math.min(remaining, item[1]);
        total += (double) taken * item[0] / item[1];
        remaining -= taken;
    }
    return total;
}

