static int pageFaultsLRU(int[] pages, int capacity) {
    if (capacity < 0) throw new IllegalArgumentException("Negative capacity");
    if (capacity == 0) return pages.length;
    LinkedHashSet<Integer> resident = new LinkedHashSet<>();
    int faults = 0;
    for (int page : pages) {
        boolean hit = resident.remove(page);
        if (!hit) {
            faults++;
            if (resident.size() == capacity) {
                Iterator<Integer> oldest = resident.iterator();
                oldest.next();
                oldest.remove();
            }
        }
        resident.add(page);
    }
    return faults;
}

