    Queue<IndexedNode> queue = new ArrayDeque<>();
    queue.offer(new IndexedNode(root, 0));
    long widest = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        long base = queue.peek().index;
        long last = 0;
        for (int i = 0; i < size; i++) {
            IndexedNode current = queue.poll();
            long index = current.index - base;
            last = index;
