                queue.offer(new IndexedNode(current.node.left, 2 * index + 1));
            if (current.node.right != null)
                queue.offer(new IndexedNode(current.node.right, 2 * index + 2));
        }
        widest = Math.max(widest, last + 1);
    }
    return Math.toIntExact(widest);
}

