static List<Integer> dfsOfGraph(int vertices, int[][] edges) {
    List<List<Integer>> graph = adjacency(vertices, edges);
    List<Integer> order = new ArrayList<>();
    if (vertices == 0) return order;
    boolean[] seen = new boolean[vertices];
    Deque<int[]> stack = new ArrayDeque<>();
    seen[0] = true;
    order.add(0);
    stack.push(new int[]{0, 0});
    while (!stack.isEmpty()) {
        int[] frame = stack.peek();
        List<Integer> neighbors = graph.get(frame[0]);
        if (frame[1] == neighbors.size()) { stack.pop(); continue; }
        int next = neighbors.get(frame[1]++);
        if (!seen[next]) {
            seen[next] = true;
            order.add(next);
            stack.push(new int[]{next, 0});
        }
    }
    return order;
}

