static int simulateRotting(int[][] grid) {
    if (grid.length == 0 || grid[0].length == 0) return 0;
    int rows = grid.length, cols = grid[0].length, fresh = 0, minutes = 0;
    for (int[] row : grid) for (int cell : row) if (cell == 1) fresh++;
    while (fresh > 0) {
        boolean changed = false;
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
            if (grid[r][c] != 2) continue;
            for (int[] direction : DIRECTIONS) {
                int nr = r + direction[0], nc = c + direction[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {
                    grid[nr][nc] = 3;
                    fresh--;
                    changed = true;
                }
            }
        }
        if (!changed) return -1;
        for (int[] row : grid) for (int c = 0; c < cols; c++) if (row[c] == 3) row[c] = 2;
        minutes++;
    }
    return minutes;
}

