static int[][] floodFill(int[][] image, int startRow, int startCol, int color) {
    int oldColor = image[startRow][startCol];
    if (oldColor == color) return image;
    int rows = image.length, cols = image[0].length;
    Deque<int[]> queue = new ArrayDeque<>();
    image[startRow][startCol] = color;
    queue.add(new int[]{startRow,startCol});
    while (!queue.isEmpty()) {
        int[] cell = queue.remove();
        for (int[] direction : DIRECTIONS) {
            int r = cell[0] + direction[0], c = cell[1] + direction[1];
            if (r >= 0 && r < rows && c >= 0 && c < cols && image[r][c] == oldColor) {
                image[r][c] = color;
                queue.add(new int[]{r,c});
            }
        }
    }
    return image;
}

