static int[][] nearestValue(int[][] matrix, int target) {
    int rows = matrix.length, cols = rows == 0 ? 0 : matrix[0].length;
    int[][] distance = new int[rows][cols];
    Deque<int[]> queue = new ArrayDeque<>();
    for (int r = 0; r < rows; r++) {
