static int[][] nearestByComparison(int[][] matrix, int target) {
    int rows = matrix.length, cols = rows == 0 ? 0 : matrix[0].length;
    List<int[]> sources = new ArrayList<>();
    for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++)
