    int[][] answer = new int[rows][cols];
    for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
        int best = Integer.MAX_VALUE;
        for (int[] source : sources) best = Math.min(best, Math.abs(r-source[0]) + Math.abs(c-source[1]));
