static void solve(char[][] board) {
    if (board.length == 0 || board[0].length == 0) return;
    int rows = board.length, cols = board[0].length;
    Deque<int[]> queue = new ArrayDeque<>();
    for (int r = 0; r < rows; r++) { enqueueSafe(board,r,0,queue); enqueueSafe(board,r,cols-1,queue); }
    for (int c = 0; c < cols; c++) { enqueueSafe(board,0,c,queue); enqueueSafe(board,rows-1,c,queue); }
    int[][] directions = {{-1,0},{1,0},{0,-1},{0,1}};
    while (!queue.isEmpty()) {
        int[] cell = queue.remove();
        for (int[] direction : directions) enqueueSafe(board,cell[0]+direction[0],cell[1]+direction[1],queue);
    }
    finishBoard(board);
}
static void enqueueSafe(char[][] board, int row, int col, Deque<int[]> queue) {
    if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] != 'O') return;
    board[row][col] = '#';
    queue.add(new int[]{row,col});
}

static void finishBoard(char[][] board) {
    for (char[] row : board) for (int c = 0; c < row.length; c++) {
        if (row[c] == 'O') row[c] = 'X';
        else if (row[c] == '#') row[c] = 'O';
    }
}

