static int ladderLength(String begin, String end, List<String> words) {
    if (begin.equals(end)) return 1;
    Set<String> unused = new HashSet<>(words);
    if (!unused.contains(end)) return 0;
    Deque<String> queue = new ArrayDeque<>();
    queue.add(begin);
    unused.remove(begin);
    int length = 1;
    while (!queue.isEmpty()) {
        int layerSize = queue.size();
        for (int i = 0; i < layerSize; i++) {
            String word = queue.remove();
            if (word.equals(end)) return length;
            char[] letters = word.toCharArray();
            for (int position = 0; position < letters.length; position++) {
                char original = letters[position];
                for (char letter = 'a'; letter <= 'z'; letter++) {
                    if (letter == original) continue;
                    letters[position] = letter;
                    String candidate = new String(letters);
                    if (unused.remove(candidate)) queue.add(candidate);
                }
                letters[position] = original;
            }
        }
        length++;
    }
    return 0;
}

