static List<List<String>> findLadders(String begin, String end, List<String> words) {
    List<List<String>> answer = new ArrayList<>();
    if (begin.equals(end)) { answer.add(new ArrayList<>(List.of(begin))); return answer; }
    Set<String> unused = new HashSet<>(words);
    if (!unused.contains(end)) return answer;
    Map<String,List<String>> parents = new HashMap<>();
    Set<String> current = new HashSet<>(List.of(begin));
    boolean found = false;
    while (!current.isEmpty() && !found) {
        unused.removeAll(current);
        Set<String> nextLevel = new HashSet<>();
        for (String word : current) {
            char[] letters = word.toCharArray();
            for (int position = 0; position < letters.length; position++) {
                char original = letters[position];
                for (char letter = 'a'; letter <= 'z'; letter++) {
                    if (letter == original) continue;
                    letters[position] = letter;
                    String candidate = new String(letters);
                    if (unused.contains(candidate)) {
                        nextLevel.add(candidate);
                        parents.computeIfAbsent(candidate, key -> new ArrayList<>()).add(word);
                        if (candidate.equals(end)) found = true;
                    }
                }
                letters[position] = original;
            }
        }
        current = nextLevel;
    }
    if (found) collectLadders(end, begin, parents, new ArrayList<>(List.of(end)), answer);
    return answer;
}
static void collectLadders(String word, String begin, Map<String,List<String>> parents,
                          List<String> reversed, List<List<String>> answer) {
    if (word.equals(begin)) {
        List<String> sequence = new ArrayList<>(reversed);
        Collections.reverse(sequence);
        answer.add(sequence);
        return;
    }
    for (String parent : parents.getOrDefault(word, Collections.emptyList())) {
        reversed.add(parent);
        collectLadders(parent, begin, parents, reversed, answer);
        reversed.remove(reversed.size()-1);
    }
}

