static List<List<String>> laddersByPaths(String begin, String end, List<String> words) {
    List<List<String>> answer = new ArrayList<>();
    if (begin.equals(end)) { answer.add(new ArrayList<>(List.of(begin))); return answer; }
    Set<String> dictionary = new HashSet<>(words);
    if (!dictionary.contains(end)) return answer;
    Map<String,Integer> depth = new HashMap<>();
    Deque<List<String>> queue = new ArrayDeque<>();
    queue.add(new ArrayList<>(List.of(begin)));
    depth.put(begin, 1);
    int shortest = Integer.MAX_VALUE;
    while (!queue.isEmpty()) {
        List<String> path = queue.remove();
        if (path.size() > shortest) break;
        String last = path.get(path.size()-1);
        if (last.equals(end)) { shortest = path.size(); answer.add(path); continue; }
        for (String next : dictionary) {
            int nextDepth = path.size()+1;
            if (oneChange(last,next) && nextDepth <= depth.getOrDefault(next,Integer.MAX_VALUE)) {
                depth.put(next,nextDepth);
                List<String> extended = new ArrayList<>(path);
                extended.add(next); queue.add(extended);
            }
        }
    }
    return answer;
}

