static int countDistinctIslands(int[][] grid) {
    Set<String> shapes = new HashSet<>();
    for (int r = 0; r < grid.length; r++) for (int c = 0; c < grid[r].length; c++) {
        if (grid[r][c] != 1) continue;
        List<int[]> cells = collectIsland(grid,r,c);
        StringBuilder signature = new StringBuilder();
        for (int[] cell : cells) signature.append(cell[0]-r).append(':').append(cell[1]-c).append('|');
        shapes.add(signature.toString());
    }
    return shapes.size();
}

