static List<Integer> eventualSafeNodes(int[][] graph) {
    int n = graph.length;
    List<List<Integer>> reverse = new ArrayList<>();
    for (int i = 0; i < n; i++) reverse.add(new ArrayList<>());
    int[] remaining = new int[n];
    for (int u = 0; u < n; u++) {
        remaining[u] = graph[u].length;
        for (int v : graph[u]) reverse.get(v).add(u);
    }
    Deque<Integer> queue = new ArrayDeque<>();
    for (int u = 0; u < n; u++) if (remaining[u] == 0) queue.add(u);
    boolean[] safe = new boolean[n];
    while (!queue.isEmpty()) {
        int vertex = queue.remove();
        safe[vertex] = true;
        for (int previous : reverse.get(vertex)) if (--remaining[previous] == 0) queue.add(previous);
    }
    List<Integer> answer = new ArrayList<>();
    for (int u = 0; u < n; u++) if (safe[u]) answer.add(u);
    return answer;
}

