static Map<Character,Set<Character>> alphabetGraph(String[] words) {
    Map<Character,Set<Character>> graph = new LinkedHashMap<>();
    for (String word : words) for (char letter : word.toCharArray()) graph.putIfAbsent(letter,new HashSet<>());
    for (int i = 0; i+1 < words.length; i++) {
        String first = words[i], second = words[i+1];
        int position = 0, limit = Math.min(first.length(),second.length());
        while (position < limit && first.charAt(position) == second.charAt(position)) position++;
        if (position == limit) {
            if (first.length() > second.length()) return null;
        } else graph.get(first.charAt(position)).add(second.charAt(position));
    }
    return graph;
}

static String alienOrder(String[] words) {
    Map<Character,Set<Character>> graph = alphabetGraph(words);
    if (graph == null) return "";
    Map<Character,Integer> indegree = new HashMap<>();
    for (char letter : graph.keySet()) indegree.put(letter,0);
    for (Set<Character> neighbors : graph.values()) for (char next : neighbors)
        indegree.put(next,indegree.get(next)+1);
    Deque<Character> queue = new ArrayDeque<>();
    for (char letter : graph.keySet()) if (indegree.get(letter) == 0) queue.add(letter);
    StringBuilder order = new StringBuilder();
    while (!queue.isEmpty()) {
        char letter = queue.remove();
        order.append(letter);
        for (char next : graph.get(letter)) {
            int remaining = indegree.get(next)-1;
            indegree.put(next,remaining);
            if (remaining == 0) queue.add(next);
        }
    }
    return order.length() == graph.size() ? order.toString() : "";
}

