    List<Integer> order = new ArrayList<>();
    while (!queue.isEmpty()) {
        int vertex = queue.remove();
        order.add(vertex);
        for (int[] edge : graph.get(vertex)) if (--indegree[edge[0]] == 0) queue.add(edge[0]);
