    for (int vertex : order) {
        if (distance[vertex] == Long.MAX_VALUE) continue;
        for (int[] edge : graph.get(vertex)) {
            long candidate = distance[vertex] + edge[1];
            distance[edge[0]] = Math.min(distance[edge[0]],candidate);
        }
    }
    return distance;
