static int matrixByRounds(int[][] grid) {
    int n = grid.length;
    if (n == 0 || grid[0][0] != 0 || grid[n-1][n-1] != 0) return -1;
    int limit = n*n;
    int[][] distance = new int[n][n];
    for (int[] row : distance) Arrays.fill(row,limit);
    distance[0][0] = 0;
    for (int round = 1; round < limit; round++) {
        boolean changed = false;
        for (int r = 0; r < n; r++) for (int c = 0; c < n; c++) {
            if (distance[r][c] == limit) continue;
            for (int dr = -1; dr <= 1; dr++) for (int dc = -1; dc <= 1; dc++) {
                int nr = r+dr, nc = c+dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0
                        && distance[r][c]+1 < distance[nr][nc]) {
                    distance[nr][nc] = distance[r][c]+1; changed = true;
                }
            }
        }
        if (!changed) break;
    }
    return distance[n-1][n-1] == limit ? -1 : distance[n-1][n-1]+1;
}

