static final int[][] DIRECTIONS = {{-1,0},{0,1},{1,0},{0,-1}};

static int minimumEffortPath(int[][] heights) {
    int rows = heights.length, cols = heights[0].length;
    int[][] effort = new int[rows][cols];
    for (int[] row : effort) Arrays.fill(row,Integer.MAX_VALUE);
    PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt((int[] state) -> state[0]));
    effort[0][0] = 0;
    heap.add(new int[]{0,0,0});
    while (!heap.isEmpty()) {
        int[] state = heap.remove();
        int cost = state[0], row = state[1], col = state[2];
        if (cost != effort[row][col]) continue;
        if (row == rows-1 && col == cols-1) return cost;
        for (int[] direction : DIRECTIONS) {
            int r = row+direction[0], c = col+direction[1];
            if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
            int candidate = Math.max(cost,Math.abs(heights[r][c]-heights[row][col]));
            if (candidate < effort[r][c]) {
                effort[r][c] = candidate;
                heap.add(new int[]{candidate,r,c});
            }
        }
    }
    throw new IllegalStateException("Every cell in a nonempty rectangular height grid is reachable");
}

