static boolean canReach(int[][] heights, int limit) {
    int rows = heights.length, cols = heights[0].length;
    boolean[][] seen = new boolean[rows][cols];
    Deque<int[]> queue = new ArrayDeque<>();
    seen[0][0] = true; queue.add(new int[]{0,0});
    while (!queue.isEmpty()) {
        int[] cell = queue.remove();
        if (cell[0] == rows-1 && cell[1] == cols-1) return true;
        for (int[] direction : DIRECTIONS) {
            int r = cell[0]+direction[0], c = cell[1]+direction[1];
            if (r >= 0 && r < rows && c >= 0 && c < cols && !seen[r][c]
                    && Math.abs(heights[r][c]-heights[cell[0]][cell[1]]) <= limit) {
                seen[r][c] = true; queue.add(new int[]{r,c});
            }
        }
    }
    return false;
}
static int heightRange(int[][] heights) {
    int minimum = heights[0][0], maximum = minimum;
    for (int[] row : heights) for (int value : row) { minimum = Math.min(minimum,value); maximum = Math.max(maximum,value); }
    return maximum-minimum;
}

static int effortByLimits(int[][] heights) {
    int maximum = heightRange(heights);
    for (int limit = 0; limit <= maximum; limit++) if (canReach(heights,limit)) return limit;
    throw new IllegalStateException("The full height range must permit a path");
}

