static long networkDelay(int[][] times, int n, int start) {
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
    for (int[] edge : times) graph.get(edge[0]).add(new int[]{edge[1],edge[2]});
    long[] distance = new long[n+1];
    Arrays.fill(distance,Long.MAX_VALUE);
    distance[start] = 0;
    PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
    heap.offer(new long[]{0,start});
    while (!heap.isEmpty()) {
        long[] entry = heap.poll();
        long arrival = entry[0];
        int node = (int) entry[1];
        if (arrival != distance[node]) continue;
        for (int[] edge : graph.get(node)) {
            long candidate = arrival + edge[1];
            if (candidate < distance[edge[0]]) {
                distance[edge[0]] = candidate;
                heap.offer(new long[]{candidate,edge[0]});
            }
        }
    }
    return lastArrival(distance);
}
static long lastArrival(long[] distance) {
    long answer = 0;
    for (int node = 1; node < distance.length; node++) {
        if (distance[node] == Long.MAX_VALUE) return -1;
        answer = Math.max(answer,distance[node]);
    }
    return answer;
}
static int networkDelayTime(int[][] times, int n, int k) {
    return Math.toIntExact(networkDelay(times,n,k));
}

