static int countPaths(int n, int[][] roads) {
    final int MOD = 1_000_000_007;
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
    for (int[] road : roads) {
        if (road[2] <= 0) throw new IllegalArgumentException("Road times must be positive");
        graph.get(road[0]).add(new int[]{road[1],road[2]});
        graph.get(road[1]).add(new int[]{road[0],road[2]});
    }
    long[] distance = new long[n];
    Arrays.fill(distance,Long.MAX_VALUE);
    int[] ways = new int[n];
    distance[0] = 0;
    ways[0] = 1;
    PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
    heap.offer(new long[]{0,0});
    while (!heap.isEmpty()) {
        long[] entry = heap.poll();
        long time = entry[0];
        int node = (int) entry[1];
        if (time != distance[node]) continue;
        for (int[] road : graph.get(node)) {
            int next = road[0];
            long candidate = time + road[1];
            if (candidate < distance[next]) {
                distance[next] = candidate;
                ways[next] = ways[node];
                heap.offer(new long[]{candidate,next});
            } else if (candidate == distance[next]) {
                ways[next] = (int)(((long)ways[next] + ways[node]) % MOD);
            }
        }
    }
    return ways[n-1];
}

