static long[][] allPairDistances(int[][] matrix) {
    int n = matrix.length;
    long[][] distance = new long[n][n];
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
        distance[i][j] = i == j ? 0 : matrix[i][j] == -1 ? Long.MAX_VALUE : matrix[i][j];
