static int findTheCity(int n, int[][] edges, int threshold) {
    long[][] distance = new long[n][n];
    for (int i = 0; i < n; i++) {
        Arrays.fill(distance[i],Long.MAX_VALUE);
        distance[i][i] = 0;
    }
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        distance[u][v] = Math.min(distance[u][v],edge[2]);
        distance[v][u] = Math.min(distance[v][u],edge[2]);
    }
    relaxAllPairs(distance);
    int answer = -1, bestCount = n;
    for (int city = 0; city < n; city++) {
        int count = 0;
        for (int other = 0; other < n; other++)
            if (other != city && distance[city][other] <= threshold) count++;
        if (count <= bestCount) { bestCount = count; answer = city; }
    }
    return answer;
}

static void relaxAllPairs(long[][] distance) {
    int n = distance.length;
    for (int middle = 0; middle < n; middle++) {
        for (int from = 0; from < n; from++) {
            if (distance[from][middle] == Long.MAX_VALUE) continue;
            for (int to = 0; to < n; to++) {
                if (distance[middle][to] == Long.MAX_VALUE) continue;
                distance[from][to] = Math.min(distance[from][to],
                    distance[from][middle] + distance[middle][to]);
            }
        }
    }
}

