static int findTheCityByHeap(int n, int[][] edges, int threshold) {
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
    for (int[] e : edges) {
        graph.get(e[0]).add(new int[]{e[1],e[2]});
        graph.get(e[1]).add(new int[]{e[0],e[2]});
    }
    int answer = -1, bestCount = n;
    for (int source = 0; source < n; source++) {
        long[] distance = new long[n];
        Arrays.fill(distance,Long.MAX_VALUE);
        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        distance[source] = 0;
        heap.offer(new long[]{0,source});
        int count = 0;
        while (!heap.isEmpty()) {
            long[] entry = heap.poll();
            int node = (int)entry[1];
            if (entry[0] != distance[node]) continue;
            if (node != source) count++;
            for (int[] edge : graph.get(node)) {
                long candidate = entry[0] + edge[1];
