static long mstBySubsets(int vertices, int[][] edges) {
    if (vertices <= 1) return 0;
    if (edges.length > 22) throw new IllegalArgumentException("Use this baseline only on small graphs");
    long best = Long.MAX_VALUE;
    for (int mask = 0; mask < (1 << edges.length); mask++) {
        if (Integer.bitCount(mask) != vertices-1) continue;
        boolean[] reached = new boolean[vertices];
        Queue<Integer> queue = new ArrayDeque<>();
        reached[0] = true;
        queue.offer(0);
        int count = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            count++;
            for (int i = 0; i < edges.length; i++) if ((mask & (1 << i)) != 0) {
                int next = edges[i][0] == node ? edges[i][1] : edges[i][1] == node ? edges[i][0] : -1;
                if (next >= 0 && !reached[next]) { reached[next] = true; queue.offer(next); }
            }
        }
        if (count != vertices) continue;
        long total = 0;
        for (int i = 0; i < edges.length; i++) if ((mask & (1 << i)) != 0) total += edges[i][2];
        best = Math.min(best,total);
    }
    return best;
}

