static class RankDSU {
    private final int[] parent, rank;
    RankDSU(int n) {
        parent = new int[n+1];
        rank = new int[n+1];
        for (int node = 1; node <= n; node++) parent[node] = node;
    }
    int findParent(int node) {
        if (parent[node] != node) parent[node] = findParent(parent[node]);
        return parent[node];
    }
    boolean unionByRank(int u, int v) {
        int a = findParent(u), b = findParent(v);
        if (a == b) return false;
        if (rank[a] < rank[b]) { int temp = a; a = b; b = temp; }
        parent[b] = a;
        if (rank[a] == rank[b]) rank[a]++;
        return true;
    }
    boolean find(int u, int v) { return findParent(u) == findParent(v); }
}

