static long kruskalWeight(int vertices, int[][] edges) {
    int[][] sorted = edges.clone(); // Sort references without changing input order.
    Arrays.sort(sorted,Comparator.comparingInt(edge -> edge[2]));
    DSU dsu = new DSU(vertices);
    int selected = 0;
    long total = 0;
    for (int[] edge : sorted) {
        if (!dsu.unite(edge[0],edge[1])) continue;
        total += edge[2];
        if (++selected == vertices-1) break;
    }
    if (vertices > 0 && selected != vertices-1)
        throw new IllegalArgumentException("Graph is disconnected");
    return total;
}
