static int makeConnectedByTraversal(int n, int[][] connections) {
    if (connections.length < n-1) return -1;
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
    for (int[] edge : connections) {
        graph.get(edge[0]).add(edge[1]); graph.get(edge[1]).add(edge[0]);
    }
    boolean[] visited = new boolean[n];
    int components = 0;
    for (int start = 0; start < n; start++) if (!visited[start]) {
        components++;
        Queue<Integer> queue = new ArrayDeque<>();
        visited[start] = true; queue.offer(start);
        while (!queue.isEmpty()) for (int next : graph.get(queue.poll()))
            if (!visited[next]) { visited[next] = true; queue.offer(next); }
    }
    return components-1;
}

