static int removeStones(int[][] stones) {
    if (stones.length == 0) return 0;
    int maxRow = 0, maxCol = 0;
    for (int[] stone : stones) { maxRow = Math.max(maxRow,stone[0]); maxCol = Math.max(maxCol,stone[1]); }
