static void finishDfs(int start, List<? extends List<Integer>> graph,
                      boolean[] seen, List<Integer> order) {
    Deque<FinishFrame> stack = new ArrayDeque<>();
    seen[start] = true; stack.push(new FinishFrame(start));
    while (!stack.isEmpty()) {
        FinishFrame frame = stack.peek();
        if (frame.next < graph.get(frame.node).size()) {
            int neighbor = graph.get(frame.node).get(frame.next++);
            if (!seen[neighbor]) { seen[neighbor] = true; stack.push(new FinishFrame(neighbor)); }
