    for (int u = 0; u < vertices; u++) for (int v : graph.get(u)) reverse.get(v).add(u);
    boolean[] seen = new boolean[vertices];
    List<Integer> order = new ArrayList<>();
    for (int start = 0; start < vertices; start++) if (!seen[start]) finishDfs(start,graph,seen,order);
    Arrays.fill(seen,false);
    int components = 0;
    for (int i = order.size()-1; i >= 0; i--) {
        int start = order.get(i);
        if (seen[start]) continue;
        components++;
