    for (int source = 0; source < vertices; source++) {
        Queue<Integer> queue = new ArrayDeque<>();
        reachable[source][source] = true; queue.offer(source);
        while (!queue.isEmpty()) for (int next : graph.get(queue.poll()))
            if (!reachable[source][next]) { reachable[source][next] = true; queue.offer(next); }
    }
    boolean[] grouped = new boolean[vertices];
    int count = 0;
    for (int u = 0; u < vertices; u++) if (!grouped[u]) {
        count++;
