static int targetRecursive(int[] values, int index, int sum, int target) {
    if (index == values.length) return sum == target ? 1 : 0;
    return targetRecursive(values,index+1,sum+values[index],target)
         + targetRecursive(values,index+1,sum-values[index],target);
}

