static int change(int amount, int[] coins) {
    return coinCombinationsExact(amount,coins).intValueExact();
}
static BigInteger coinCombinationsExact(int amount, int[] coins) {
    BigInteger[] ways = new BigInteger[amount+1];
    Arrays.fill(ways,BigInteger.ZERO);
    ways[0] = BigInteger.ONE;
    for (int coin : coins) {
        for (int sum = coin; sum <= amount; sum++) {
            ways[sum] = ways[sum].add(ways[sum-coin]);
        }
    }
    return ways[amount];
}

