static BigInteger combinationsRecursive(int[] coins, int index, int remaining) {
    if (remaining == 0) return BigInteger.ONE;
    if (index < 0) return BigInteger.ZERO;
    BigInteger skip = combinationsRecursive(coins,index-1,remaining);
    BigInteger take = coins[index] <= remaining
        ? combinationsRecursive(coins,index,remaining-coins[index]) : BigInteger.ZERO;
    return skip.add(take);
}

