static BigInteger combinationsMemoized(int amount, int[] coins) {
    return combinationsMemo(coins,coins.length-1,amount,new BigInteger[coins.length][amount+1]);
}
static BigInteger combinationsMemo(int[] coins, int index, int remaining, BigInteger[][] memo) {
    if (remaining == 0) return BigInteger.ONE;
    if (index < 0) return BigInteger.ZERO;
    if (memo[index][remaining] != null) return memo[index][remaining];
    BigInteger skip = combinationsMemo(coins,index-1,remaining,memo);
    BigInteger take = coins[index] <= remaining
        ? combinationsMemo(coins,index,remaining-coins[index],memo) : BigInteger.ZERO;
    return memo[index][remaining] = skip.add(take);
}
static BigInteger combinationsTable(int amount, int[] coins) {
    BigInteger[][] dp = new BigInteger[coins.length+1][amount+1];
    for (BigInteger[] row : dp) { Arrays.fill(row,BigInteger.ZERO); row[0] = BigInteger.ONE; }
    for (int used = 1; used <= coins.length; used++) {
        int coin = coins[used-1];
        for (int sum = 1; sum <= amount; sum++) {
            BigInteger take = coin <= sum ? dp[used][sum-coin] : BigInteger.ZERO;
            dp[used][sum] = dp[used-1][sum].add(take);
        }
    }
    return dp[coins.length][amount];
}
